from collections import deque
from typing import List

class Solution:
    def maxDistance(self, grid: List[List[int]]) -> int:
        n = len(grid)
        q = deque()
        has_land = False
        has_water = False

        for i in range(n):
            for j in range(n):
                if grid[i][j] == 1:
                    has_land = True
                    q.append((i, j, 0))
                else:
                    has_water = True

        if not has_land or not has_water:
            return -1

        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        max_dist = 0

        while q:
            r, c, dist = q.popleft()
            max_dist = dist

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] == 0:
                    grid[nr][nc] = 1
                    q.append((nr, nc, dist + 1))

        return max_dist
